522	    <header>
523	        <div class="header-container">
524	            <h1>Welcome</h1>
525	            <button class="menu-toggle" aria-label="Toggle navigation menu" aria-controls="nav-menu" aria-expanded="false">☰</button>
526	            <nav aria-label="Primary navigation">
527	                <ul id="nav-menu">
