557	        <article id="get-started">
558	            <h2>Get Started</h2>
559	            <p>
560	                Use this template as a foundation for your next project. It's clean, well-structured, and ready to be
561	                customized to meet your specific needs.
562	            </p>
563	            <form id="contact-form" method="POST" data-endpoint="/contact">
564	                <fieldset>
565	                    <legend>Get in Touch</legend>
566	                    <p class="form-info"><span class="required" style="font-weight: 600;">*</span> indicates required fields</p>
567	                    <div class="form-group">
568	                        <label for="name" class="required">Name</label>
569	                        <input type="text" id="name" name="name" placeholder="Your full name" required aria-required="true" aria-describedby="name-error" minlength="2" pattern="[A-Za-z\s]{2,}">
570	                        <div class="field-error" id="name-error"></div>
571	                    </div>
572	                    <div class="form-group">
573	                        <label for="email" class="required">Email</label>
574	                        <input type="email" id="email" name="email" placeholder="you@example.com" required aria-required="true" aria-describedby="email-error">
575	                        <div class="field-error" id="email-error"></div>
576	                    </div>
577	                    <div class="form-group">
578	                        <label for="message" class="required">Message</label>
579	                        <textarea id="message" name="message" placeholder="Tell us what you think..." required aria-required="true" aria-describedby="message-error"></textarea>
580	                        <div class="field-error" id="message-error"></div>
581	                    </div>
582	                    <button type="submit" class="cta-button" id="submit-btn">Send Message</button>
583	                    <div id="form-feedback" class="form-feedback" role="alert" aria-live="polite"></div>
584	                </fieldset>
