618	    <script>
619	        document.addEventListener('DOMContentLoaded', function() {
620	            document.getElementById('year').textContent = new Date().getFullYear();
621	
622	            const menuToggle = document.querySelector('.menu-toggle');
623	            const navMenu = document.getElementById('nav-menu');
624	
625	            if (menuToggle) {
626	                const closeMenu = () => {
627	                    menuToggle.setAttribute('aria-expanded', 'false');
628	                    navMenu.setAttribute('hidden', '');
629	                    menuToggle.focus();
630	                };
631	
632	                menuToggle.addEventListener('click', function() {
633	                    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
634	                    menuToggle.setAttribute('aria-expanded', !isExpanded);
635	                    navMenu.toggleAttribute('hidden');
636	                });
637	
638	                document.addEventListener('keydown', (e) => {
639	                    if (e.key === 'Escape' && menuToggle.getAttribute('aria-expanded') === 'true') {
640	                        closeMenu();
641	                    }
642	                });
643	
644	                const navLinks = navMenu.querySelectorAll('a');
645	                navLinks.forEach(link => {
646	                    link.addEventListener('click', closeMenu);
647	                });
648	            }
649	
650	            const learnMoreBtn = document.getElementById('learn-more-btn');
651	            if (learnMoreBtn) {
652	                learnMoreBtn.addEventListener('click', function() {
653	                    const getStartedSection = document.getElementById('get-started');
654	                    if (getStartedSection) {
655	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
656	                        document.getElementById('name').focus();
657	                    }
658	                });
659	            }
660	
661	            const contactForm = document.getElementById('contact-form');
662	            if (contactForm) {
663	                const showError = (field, message) => {
664	                    const error = field.parentElement.querySelector('.field-error');
665	                    if (error) {
666	                        error.classList.add('show');
667	                        error.textContent = message;
668	                    }
669	                    field.setAttribute('aria-invalid', 'true');
670	                };
671	
672	                const clearError = (field) => {
673	                    const error = field.parentElement.querySelector('.field-error');
674	                    if (error) {
675	                        error.classList.remove('show');
676	                    }
677	                    field.setAttribute('aria-invalid', 'false');
678	                };
679	
680	                const validateField = (field) => {
681	                    const value = field.value.trim();
682	
683	                    if (!value) {
684	                        showError(field, 'This field is required');
685	                        return false;
686	                    }
687	
688	                    if (!field.checkValidity()) {
689	                        let message = 'Invalid input';
690	                        if (field.type === 'email') {
691	                            message = 'Please enter a valid email address';
692	                        } else if (field.id === 'name') {
693	                            message = 'Name must contain at least 2 letters';
694	                        } else if (field.id === 'message') {
695	                            message = 'Please provide a message';
696	                        }
697	                        showError(field, message);
698	                        return false;
699	                    }
700	
701	                    clearError(field);
702	                    return true;
703	                };
704	
705	                const inputs = contactForm.querySelectorAll('input, textarea');
706	                inputs.forEach(input => {
707	                    input.addEventListener('blur', () => validateField(input));
708	                });
709	
710	                contactForm.addEventListener('submit', function(e) {
711	                    e.preventDefault();
712	                    let isValid = true;
713	                    const feedback = document.getElementById('form-feedback');
714	                    feedback.className = 'form-feedback';
715	
716	                    inputs.forEach(input => {
717	                        if (!validateField(input)) isValid = false;
718	                    });
719	
720	                    if (!isValid) {
721	                        feedback.className = 'form-feedback error';
722	                        feedback.textContent = 'Please correct the errors above and try again.';
723	                        feedback.focus();
724	                        return;
725	                    }
726	
727	                    const submitBtn = document.getElementById('submit-btn');
